Q: Changing an image if an id or tag is found within HTML file A: <p>Change the HTML that is included in the <code>MenuContent</code> variable, so that it is generic (no reference to any color) and use CSS to style the menu according to a class name defined somewhere. In the following example I have a class name on <code>&lt;body&gt;</code> named <code>menu-green</code>. And based on that different images will be used as a background for the <code>navigationcontainer</code>. So, instead of creating image elements (<code>&lt;img&gt;</code>) with the colored image, you will have to include the images as background images in CSS.</p>
<p>The data URL included in the example is your JavaScript file (so that I can refer to it like a file here on StackOverflow):</p>
<pre class="lang-js prettyprint-override"><code>let MenuContent = `
&lt;div class='navigationcontainer' style='margin-top:10px;'&gt;
  &lt;a href='https://rootpain.com/index.html'&gt;
    &lt;div class='buttoncontainer'&gt;
      &lt;img src='./images/menus/homebuttonfaded.png' class='buttonfade'&gt;
      &lt;img src='./images/menus/homebutton.png' class='button'&gt;
      &lt;img src='./images/menus/homebuttonslide.png' class='buttonslide'&gt;
    &lt;/div&gt;
&lt;/div&gt;`;
</code></pre>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-css lang-css prettyprint-override"><code>nav div.navigationcontainer {
  background-repeat: no-repeat;
  width: 230px;
  padding-top: 30px;
}

body.green-menu nav div.navigationcontainer {
  background-image: url('https://placehold.co/230x30/2dc863/FFF');
}

body.blue-menu nav div.navigationcontainer {
  background-image: url('https://placehold.co/230x30/1f5a8d/FFF');
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;html&gt;

&lt;head&gt;
  &lt;meta charset="utf-8"&gt;
  &lt;title&gt;Green page&lt;/title&gt;
  &lt;script src="data:text/javascript;base64,"&gt;&lt;/script&gt;
  &lt;script&gt;
    document.addEventListener('DOMContentLoaded', e =&gt; {
      document.getElementById('nav').innerHTML = MenuContent;
    });
  &lt;/script&gt;
&lt;/head&gt;

&lt;body class="green-menu"&gt;
  &lt;nav id="nav"&gt;&lt;/nav&gt;
&lt;/body&gt;

&lt;/html&gt;</code></pre>
</div>
</div>
</p>

Q: min/max width/height with multiple values A: <p>create separate classes and add them dynamically based on outerWidth()</p>
<pre class="lang-css prettyprint-override"><code>.some_element {
    background: red;
    float: left;
    width: auto;
}

.widthClass1{
  max-width:50%;
}

.widthClass2{
  max-width:200px;
}
</code></pre>
<pre class="lang-js prettyprint-override"><code>$(document).ready(function(){
    if($(&quot;textDiv&quot;).outerWidth()&lt;400){//instead of dividing by 2 I am comparing with 400
      $(&quot;textDiv&quot;).addClass('widthClass1')
    }else{
      $(&quot;textDiv&quot;).addClass('widthClass2')
    }
});
</code></pre>

Q: keydown not detected until window is clicked A: <pre><code>&lt;!-- Hidden focusable element for keyboard capture --&gt;
&lt;div id=&quot;kbdCapture&quot; tabindex=&quot;-1&quot; 
     style=&quot;position: absolute; width: 0; height: 0; overflow: hidden; opacity: 0;&quot;&gt;
&lt;/div&gt;

&lt;div id=&quot;myModal&quot;&gt;
  &lt;!-- Your modal content --&gt;
&lt;/div&gt;
</code></pre>
<pre><code>// When modal opens
function openModal() {
  const modal = document.getElementById('myModal');
  const kbdCapture = document.getElementById('kbdCapture');

  modal.style.display = 'block';

  // Add keyboard listener with capture phase
  window.addEventListener('keydown', handleKeydown, { capture: true });

  // Focus the hidden element after DOM updates
  requestAnimationFrame(() =&gt; {
    kbdCapture.focus({ preventScroll: true });
  });
}

// When modal closes
function closeModal() {
  window.removeEventListener('keydown', handleKeydown, { capture: true });
}

function handleKeydown(event) {
  // Ignore if user is typing in an input
  // your logic
}
</code></pre>

Q: How can I load all municipalities into a dropdown without running out of memory? A: <p>OK. This is simple to do. I don't have access to your country file so I don't know how it is scoped or broken up, IE arrays or JSON. So my code is just a mash of yours and it will not work. But it shows how you can solve your problem with a fast end result for the user experience.</p>

<p>The trick is just to load the data that is needed when you need it. Usually this is done with an API, you call it via ajax tell it what you want and boom it sends it back so your UI can show it.</p>

<p>In this scenario we don't have a server so we will do it by dynamically loading scripts into the dom. In this case country data filled with states and City's. One file per country when requested.</p>

<p>It would be better to load state data then cities per state and so on. As well as  potentially considering if data should be removed from the Dom if memory is an issue:</p>

<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>//
// Some globals to store what the user selects.
//
VAR _COUNTY, _STATE, _CITY;

//
// This will append scripts to the body so that you dont need to load all the 
// scripts in one go, this is the trick.
//
function addScript( src,callback) {
  var s = document.createElement( 'script' );
  s.setAttribute( 'src', src );
  s.onload=callback;
  document.body.appendChild( s );
}
//
// Get all the states based on country
// add the correct file to the dom
// ie: country/Canada.js
// these files would be better scoped geodata.country geodata.state.
//
// IMPORTANT CHANGE YOUR HTML SELECT HANDLER TO FIRE HERE.
// &lt;select name="country" id="country" onchange="getStates();"&gt;
//
function getStates(){
	_COUNRTY = document.getElementById('country'),
	file = ["country/",_COUNTRY,".js"].join;
	addScript(file, setStates);	
};
//
// 
// Called when the script loads
//
function setStates() {
//
// Here is where we would do
// geodata.states for now I'm using your declaration of state.
//
var stateList = states;
changeSelect('state', stateList, stateList);
// Not sure why you are doing this they need to select a state first?
setCities();
}
//
// Called when they select a state, 
// I would replicate the state code and load all the cities per state.
// I would disable the city drop down until the states are loaded.
//
function setCities() {
_STATE = document.getElementById('state');
cityList = cities[_COUNTRY][_STATE];
changeSelect('city', cityList, cityList);
}

function changeSelect(fieldID, newOptions, newValues) {
selectField = document.getElementById(fieldID);
selectField.options.length = 0;
for (i=0; i&lt;newOptions.length; i++) {
selectField.options[selectField.length]=newOption(newOptions[i],newValues[i]);
}
}

function addLoadEvent(func) {
var oldonload = window.onload;
if (typeof window.onload != 'function') {
window.onload = func;
} else {
window.onload = function() {
if (oldonload) {
oldonload();
}
func();
}
}
}

addLoadEvent(function() {
setStates();
});

